-- Šema identična starom programu (MariaDB -> SQLite)
CREATE TABLE IF NOT EXISTS "car_make" ("id" TEXT, "name" TEXT, "icon" TEXT, "active" INTEGER, "the_protected" INTEGER, "modified_by_id" TEXT, "modified_date" TEXT, "external_olx_id" TEXT, "external_pa_id" TEXT, "external_car2db_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "car_model" ("id" TEXT, "name" TEXT, "generation_name" TEXT, "restyling" INTEGER, "restyling_second" INTEGER, "make_id" TEXT, "date_from" TEXT, "date_to" TEXT, "active" INTEGER, "modified_by_id" TEXT, "modified_date" TEXT, "created_by_id" INTEGER, "created_date" TEXT, "external_id" TEXT, "external_car2db_gen_id" TEXT, "external_car2db_model_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_auth" ("role_name" TEXT, "title" TEXT, "category_code" TEXT, "active" INTEGER, PRIMARY KEY ("role_name"));
CREATE TABLE IF NOT EXISTS "core_auth_category" ("code" TEXT, "name" TEXT, "active" INTEGER, "path" TEXT, "app" INTEGER, PRIMARY KEY ("code"));
CREATE TABLE IF NOT EXISTS "core_configuration" ("name" TEXT, "licence" TEXT, "string_value" TEXT, "int_value" INTEGER, "date_value" TEXT, "double_value" REAL, "boolean_value" INTEGER, PRIMARY KEY ("name","licence"));
CREATE TABLE IF NOT EXISTS "core_currency" ("code" TEXT, "active" INTEGER, PRIMARY KEY ("code"));
CREATE TABLE IF NOT EXISTS "core_email_template" ("id" INTEGER, "title" TEXT, "subject" TEXT, "text" TEXT, "status" TEXT, "type" TEXT, "active" INTEGER, "licence" TEXT, "layout_id" INTEGER, "last_modified_by_id" INTEGER, "last_modified" TEXT, "template_key" TEXT, "content_type" TEXT, "html" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_factory_task" ("task_id" TEXT, "enabled" INTEGER, "licence" TEXT, "last_execution" TEXT, "note" TEXT, "second" TEXT, "minute" TEXT, "hour" TEXT, "day_of_month" TEXT, "month" TEXT, "day_of_week" TEXT, "year" TEXT, PRIMARY KEY ("task_id","licence"));
CREATE TABLE IF NOT EXISTS "core_licence" ("licence_id" TEXT, "description" TEXT, "active" INTEGER, "default_licence" INTEGER, PRIMARY KEY ("licence_id"));
CREATE TABLE IF NOT EXISTS "core_login_history" ("id" INTEGER, "user_id" TEXT, "login_time" TEXT, "logout_time" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_message" ("id" INTEGER, "type" TEXT, "subject" TEXT, "html" TEXT, "status" TEXT, "created_time" TEXT, "send_time" TEXT, "receiver_address" TEXT, "receiver_id" INTEGER, "note" TEXT, "licence" TEXT, "time_for_send" TEXT, "time_to_try" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_profile" ("id" INTEGER, "name" TEXT, "description" TEXT, "licence" TEXT, "active" INTEGER, "dashboard_id" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_role" ("id" INTEGER, "name" TEXT, "code" TEXT, "description" TEXT, "the_type" TEXT, "user_id" TEXT, "licence" TEXT, "active" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_role_auth" ("role_id" INTEGER, "authority" TEXT, PRIMARY KEY ("role_id","authority"));
CREATE TABLE IF NOT EXISTS "core_role_profile" ("role_id" INTEGER, "profile_id" INTEGER, PRIMARY KEY ("role_id","profile_id"));
CREATE TABLE IF NOT EXISTS "core_user" ("id" TEXT, "firstname" TEXT, "lastname" TEXT, "phone" TEXT, "username" TEXT, "password" TEXT, "active" INTEGER, "visible" INTEGER, "email" TEXT, "default_locale" TEXT, "credentials_date" TEXT, "credentials_expiration_not_allowed" INTEGER, "account_non_expired" INTEGER, "account_non_locked" INTEGER, "licence" TEXT, "identifier" TEXT, "note" TEXT, "image" TEXT, "full_name" TEXT, "session_duration" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "core_user_profile" ("user_id" TEXT, "profile_id" INTEGER, "profile_order" REAL, PRIMARY KEY ("user_id","profile_id"));
CREATE TABLE IF NOT EXISTS "core_wdg_registry" ("id" INTEGER, "widget_class" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "dsh" ("id" INTEGER, "name" TEXT, "licence" TEXT, "active" INTEGER, "published" INTEGER, "default_dsh" INTEGER, "full_size" INTEGER, "purpose" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "dsh_row" ("id" INTEGER, "dashboard_id" INTEGER, "the_order" REAL, "created_by_id" INTEGER, "title" TEXT, "background_color" TEXT, "bottom_color" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "dsh_row_col" ("id" INTEGER, "row_id" INTEGER, "column_no" INTEGER, "width" INTEGER, "active" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "dsh_wdg" ("id" TEXT, "row_id" INTEGER, "column_id" INTEGER, "position" INTEGER, "widget_class" TEXT, "config_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "dsh_wdg_conf" ("id" TEXT, "title" TEXT, "custom_string_1" TEXT, "custom_string_2" TEXT, "custom_int_1" INTEGER, "custom_int_2" INTEGER, "custom_boolean_1" INTEGER, "custom_boolean_2" INTEGER, "default_view" INTEGER, "title_description_view" INTEGER, "refresh" INTEGER, "custom_double_1" REAL, "custom_double_2" REAL, "custom_date_1" TEXT, "custom_date_2" TEXT, "custom_text_1" TEXT, "border" TEXT, "border_color" TEXT, "border_position" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "lib_attachment" ("id" TEXT, "type" TEXT, "object_id" TEXT, "main_picture" INTEGER, "file_size" REAL, "licence" TEXT, "active" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, "external_pa_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "req" ("id" TEXT, "part_id" TEXT, "rims_id" TEXT, "location_id" TEXT, "description" TEXT, "the_number" TEXT, "status" TEXT, "urgent" INTEGER, "shipment" INTEGER, "parent_id" TEXT, "licence" TEXT, "active" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "realization_by_id" TEXT, "realization_date" TEXT, "closed_by_id" TEXT, "closed_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "req_number" ("id" TEXT, "increment" INTEGER, "licence" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "rims" ("id" TEXT, "internal_code" TEXT, "type_id" TEXT, "diameter_id" TEXT, "width_id" TEXT, "pattern_id" TEXT, "vehicle_id" TEXT, "car_make_id" TEXT, "car_model_id" TEXT, "location_id" TEXT, "damaged" INTEGER, "screw_included" INTEGER, "chrome_nickel_plated" INTEGER, "status" TEXT, "offSet" TEXT, "center_hole" REAL, "price" REAL, "currency_id" TEXT, "sale_history_id" TEXT, "note" TEXT, "licence" TEXT, "active" INTEGER, "external_olx_id" TEXT, "external_olx_date" TEXT, "external_pa_id" TEXT, "external_pa_date" TEXT, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "rims_bolt_pattern" ("id" TEXT, "bolt_number" INTEGER, "bolt_distance" TEXT, "external_pa_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "rims_diameter" ("id" TEXT, "title" TEXT, "external_olx_id" TEXT, "external_pa_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "rims_type" ("id" TEXT, "title" TEXT, "active" INTEGER, "external_olx_id" TEXT, "external_pa_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "rims_width" ("id" TEXT, "title" TEXT, "external_pa_id" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part" ("id" TEXT, "catalog_number" TEXT, "title" TEXT, "catalog_number_manufacturer" TEXT, "catalog_number_damaged" INTEGER, "internal_code" TEXT, "type_id" TEXT, "location_id" TEXT, "make_id" TEXT, "model_id" TEXT, "model_year" INTEGER, "gearbox_code" TEXT, "gearbox_type" TEXT, "gearbox_speed" INTEGER, "engine_code" TEXT, "vehicle_id" TEXT, "fuel_type" TEXT, "cylinder_capacity" REAL, "power" INTEGER, "mileage" INTEGER, "chassis_number" TEXT, "engine_number" TEXT, "color" TEXT, "drive_train" TEXT, "side" TEXT, "vehicle_type" TEXT, "part_set" INTEGER, "damaged" INTEGER, "status" TEXT, "price" REAL, "currency_id" TEXT, "sale_history_id" TEXT, "parent_id" TEXT, "parent_detached" INTEGER, "note" TEXT, "licence" TEXT, "active" INTEGER, "external_olx_id" TEXT, "external_olx_date" TEXT, "external_pa_id" TEXT, "external_pa_date" TEXT, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part_group" ("id" TEXT, "title" TEXT, "catalog_number_required" INTEGER, "licence" TEXT, "active" INTEGER, "share_engine_data" INTEGER, "share_engine_code" INTEGER, "share_gearbox_data" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part_location_history" ("id" INTEGER, "part_id" TEXT, "rims_id" TEXT, "location_id" TEXT, "action" TEXT, "created_by_id" TEXT, "created_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part_number" ("id" TEXT, "licence" TEXT, "increment" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part_sale_history" ("id" TEXT, "part_id" TEXT, "rims_id" TEXT, "the_price" REAL, "currency_id" TEXT, "note" TEXT, "status" TEXT, "licence" TEXT, "created_by_id" TEXT, "created_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part_type" ("id" TEXT, "title" TEXT, "group_id" TEXT, "external_olx_id" INTEGER, "external_pa_id" INTEGER, "title_pa" TEXT, "catalog_number_required" INTEGER, "engine_number_visible" INTEGER, "part_set_visible" INTEGER, "sides" TEXT, "licence" TEXT, "active" INTEGER, "share_engine_data" INTEGER, "share_engine_code" INTEGER, "share_gearbox_data" INTEGER, "share_all_wheel_drive" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spare_part_type_children" ("type_id" TEXT, "child_id" TEXT, PRIMARY KEY ("type_id","child_id"));
CREATE TABLE IF NOT EXISTS "spt_external_olx" ("id" INTEGER, "title" TEXT, "the_data" TEXT, "active" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spt_external_pa" ("id" INTEGER, "title" TEXT, "group_id" INTEGER, "active" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "spt_group_external_pa" ("id" INTEGER, "title" TEXT, "active" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "vehicle" ("id" TEXT, "internal_code" TEXT, "make_id" TEXT, "model_id" TEXT, "model_year" INTEGER, "mileage" INTEGER, "chassis_number" TEXT, "engine_number" TEXT, "engine_code" TEXT, "fuel_type" TEXT, "cylinder_capacity" REAL, "power" INTEGER, "gearbox_code" TEXT, "gearbox_type" TEXT, "gearbox_speed" INTEGER, "the_type" TEXT, "color" TEXT, "drive_train" TEXT, "rims_type_id" TEXT, "rims_diameter_id" TEXT, "rims_width_id" TEXT, "rims_pattern_id" TEXT, "rims_offSet" TEXT, "rims_center_hole" REAL, "note" TEXT, "price" REAL, "currency_id" TEXT, "status" TEXT, "active" INTEGER, "licence" TEXT, "youtube_url" TEXT, "external_olx_id" TEXT, "external_olx_date" TEXT, "external_pa_id" TEXT, "external_pa_date" TEXT, "modified_by_id" TEXT, "created_by_id" TEXT, "deleted_by_id" TEXT, "modified_date" TEXT, "created_date" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "vehicle_number" ("id" TEXT, "licence" TEXT, "increment" INTEGER, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "whs" ("id" TEXT, "title" TEXT, "licence" TEXT, "active" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "whs_ast" ("id" TEXT, "parent_id" TEXT, "whs_id" TEXT, "ast_type_id" TEXT, "code" INTEGER, "additional_code" TEXT, "code_extended" TEXT, "path" TEXT, "parent_path" TEXT, "licence" TEXT, "active" INTEGER, "ladder_first_level" INTEGER, "ladder_second_level" INTEGER, "forklift" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "whs_ast_location_history" ("id" INTEGER, "asset_id" TEXT, "parent_id" TEXT, "created_by_id" TEXT, "created_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "whs_ast_type" ("id" TEXT, "title" TEXT, "code" TEXT, "code_strategy" TEXT, "base" INTEGER, "parts_allowed" INTEGER, "code_edit_allowed" INTEGER, "move_allowed" INTEGER, "height_details_allowed" INTEGER, "the_order" REAL, "licence" TEXT, "active" INTEGER, "created_by_id" TEXT, "created_date" TEXT, "modified_by_id" TEXT, "modified_date" TEXT, "deleted_by_id" TEXT, "deleted_date" TEXT, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "whs_ast_type_children" ("type_id" TEXT, "type_child_id" TEXT, "the_order" REAL, PRIMARY KEY ("type_id","type_child_id"));
